package br.com.lealinfo.vidraceiro;
import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;
/** Presentation only: never reads/writes project data or replaces control listeners. */
final class InteriorVisuals {
 static final int INK=0xff03101f,WHITE=0xffe5f4fb,MUTED=0xffacc4d6,CYAN=0xff31c9ee;
 static int dp(Context c,float x){return Math.round(x*c.getResources().getDisplayMetrics().density);}
 static GradientDrawable surface(Context c,int color,boolean focus){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,0xff07192b});d.setCornerRadius(dp(c,13));d.setStroke(dp(c,focus?2:1),focus?CYAN:0xff28506a);return d;}
 static Drawable field(Context c){StateListDrawable d=new StateListDrawable();d.addState(new int[]{-android.R.attr.state_enabled},surface(c,0xff111c29,false));d.addState(new int[]{android.R.attr.state_focused},surface(c,0xff12344a,true));d.addState(new int[]{},surface(c,0xff102538,false));return d;}
 static Drawable action(Context c,boolean destructive,boolean primary){int color=destructive?0xff633043:primary?0xff116388:0xff15344d;StateListDrawable s=new StateListDrawable();s.addState(new int[]{android.R.attr.state_pressed},surface(c,destructive?0xff874357:0xff197fa1,true));s.addState(new int[]{android.R.attr.state_focused},surface(c,color,true));s.addState(new int[]{},surface(c,color,false));return new RippleDrawable(ColorStateList.valueOf(0x4435cfff),s,null);}
 static void header(MainActivity a,String page,String heading){LinearLayout signature=new LinearLayout(a);signature.setGravity(Gravity.CENTER_VERTICAL);ImageView av=new ImageView(a);av.setImageResource(R.drawable.brand_foreground);signature.addView(av,new LinearLayout.LayoutParams(a.px(39),a.px(38)));TextView brand=new TextView(a);brand.setText("ANGRA VIDROS");brand.setTextColor(CYAN);brand.setTextSize(12);brand.setLetterSpacing(.12f);signature.addView(brand);a.root.addView(signature);
 LinearLayout title=new LinearLayout(a);title.setGravity(Gravity.CENTER_VERTICAL);title.setPadding(a.px(12),a.px(12),a.px(10),a.px(12));title.setBackground(surface(a,0xff10324b,false));HomeVisuals.Icon icon=new HomeVisuals.Icon(a,index(page,heading));title.addView(icon,new LinearLayout.LayoutParams(a.px(30),a.px(30)));TextView name=new TextView(a);name.setText(heading);name.setTag("interior-heading");name.setTextSize(23);name.setTypeface(null,Typeface.BOLD);name.setTextColor(WHITE);name.setPadding(a.px(12),0,0,0);title.addView(name,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.px(12);a.root.addView(title,lp);}
 static int index(String p,String h){if(p.startsWith("cut"))return 9;if(p.equals("drawing"))return 10;if(p.equals("budget"))return 0;if(p.equals("contract"))return 4;if(p.equals("tempera"))return 3;if(p.contains("aterial"))return 8;if(p.equals("calculator"))return 6;if(h.contains("Forneced"))return 7;if(h.contains("Financeiro"))return 5;if(h.contains("Estoque"))return 11;if(p.contains("contact"))return 1;return 2;}
 static void install(MainActivity a,LinearLayout target){IdentityHashMap<View,Boolean> seen=new IdentityHashMap<>();target.getViewTreeObserver().addOnGlobalLayoutListener(()->{if(a.root==target&&!a.page.equals("home"))decorate(a,target,seen,false);});}
 static void decorate(Context c,View v,IdentityHashMap<View,Boolean> seen,boolean dialog){if(!seen.containsKey(v)){seen.put(v,true);
 if(v instanceof EditText){EditText e=(EditText)v;e.setBackground(field(c));e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setHighlightColor(0x6631c9ee);e.setPadding(dp(c,13),dp(c,12),dp(c,13),dp(c,12));e.setMinHeight(dp(c,50));if(e instanceof AutoCompleteTextView)((AutoCompleteTextView)e).setDropDownBackgroundDrawable(surface(c,0xff102538,false));}
 else if(v instanceof CheckBox){CheckBox b=(CheckBox)v;b.setTextColor(WHITE);b.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{CYAN,MUTED}));b.setMinHeight(dp(c,48));b.setPadding(dp(c,4),dp(c,6),dp(c,4),dp(c,6));}
 else if(v instanceof Button){Button b=(Button)v;String label=b.getText().toString().toUpperCase(Locale.ROOT);boolean danger=label.startsWith("EXCLUIR")||label.startsWith("REMOVER");boolean primary=label.startsWith("SALVAR")||label.startsWith("CALCULAR")||label.startsWith("RECALCULAR")||label.startsWith("+");b.setBackground(action(c,danger,primary));b.setTextColor(WHITE);b.setMinHeight(dp(c,dialog?48:50));b.setPadding(dp(c,dialog?8:14),dp(c,10),dp(c,dialog?8:14),dp(c,10));b.setElevation(dp(c,1));if(dialog){b.setTextSize(12);b.setMinWidth(0);}}
 else if(v instanceof Spinner){Spinner s=(Spinner)v;s.setBackground(field(c));s.setMinimumHeight(dp(c,48));s.setPopupBackgroundDrawable(surface(c,0xff112a40,false));s.setPadding(dp(c,8),0,dp(c,8),0);}
 else if(v instanceof TextView){TextView t=(TextView)v;t.setTextColor(dialog?WHITE:t.getCurrentTextColor());if(!dialog&&!"interior-heading".equals(t.getTag())&&t.getTextSize()/c.getResources().getDisplayMetrics().scaledDensity>=18){t.setBackground(surface(c,0xff102a3e,false));t.setPadding(dp(c,12),dp(c,12),dp(c,12),dp(c,12));}else if(dialog)t.setLineSpacing(dp(c,2),1);}
 else if(v instanceof LinearLayout&&v.getBackground() instanceof GradientDrawable){v.setBackground(surface(c,0xff0d263b,false));}
 }
 if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)decorate(c,g.getChildAt(i),seen,dialog);}}
 static final class Dialog extends AlertDialog.Builder {final Context c;Dialog(Context c){super(c);this.c=c;}@Override public AlertDialog show(){AlertDialog d=super.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(surface(c,0xff0a2237,false));View root=w.getDecorView();IdentityHashMap<View,Boolean> seen=new IdentityHashMap<>();root.getViewTreeObserver().addOnGlobalLayoutListener(()->decorate(c,root,seen,true));decorate(c,root,seen,true);}return d;}}
}
